#include <stdlib.h>
#include <string.h>

#include "elf.h"
#include "sdb.h"

Sdb* process_version_definitions(ELFOBJ *bin, Elf_Shdr *shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    // Allocate memory for version definitions
    char *strtab = NULL;
    Elf_Verdef *verdef = (Elf_Verdef*)(bin->buf + shdr->sh_offset);
    Sdb *sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    // Retrieve section names
    Elf_Shdr *verdefs_section = NULL;
    for (int i = 0; i < bin->ehdr.e_shnum; i++) {
        if (bin->shdr[i].sh_type == SHT_GNU_verdef) {
            verdefs_section = &bin->shdr[i];
            break;
        }
    }

    if (!verdefs_section) {
        sdb_free(sdb);
        return NULL;
    }

    strtab = bin->strtab + verdefs_section->sh_link;
    if (!strtab) {
        sdb_free(sdb);
        return NULL;
    }

    while ((unsigned long)(verdef - (Elf_Verdef*)bin->buf) < sz) {
        Elf_Verdef *vd = verdef;
        if (vd->vd_version != VER_DEF_CURRENT) {
            sdb_free(sdb);
            return NULL;
        }

        Elf_Verdaux *vda = (Elf_Verdaux*)((char*)vd + sizeof(Elf_Verdef));
        char *name = strtab + vda->vda_name;

        if (!sdb_num_put(sdb, name, vd->vd_ndx, NULL)) {
            sdb_free(sdb);
            return NULL;
        }

        verdef = (Elf_Verdef*)((char*)vda + vda->vda_next);
    }

    return sdb;
}

Sdb* process_version_definitions(ELFOBJ* bin, Elf_(Shdr)* shdr, int sz) {
    if (!shdr || !bin) {
        return NULL;
    }

    void* data = calloc(1, sz);
    if (!data) {
        return NULL;
    }

    char* secname = elf_strptr(bin->elf, shdr->sh_link, shdr->sh_name);
    if (!secname) {
        free(data);
        return NULL;
    }

    Sdb* sdb = sdb_new0();
    if (!sdb) {
        free(data);
        return NULL;
    }

    uint8_t* cursor = data;
    while ((size_t)(cursor - (uint8_t*)data) < sz) {
        uint16_t ndx = *(uint16_t*)cursor;
        uint16_t len = *(uint16_t*)(cursor + 2);
        cursor += 4;

        if (len > sz) {
            sdb_free(sdb);
            free(data);
            return NULL;
        }

        char* version_name = (char*)cursor;
        if (sdb_num_put(sdb, version_name, (ut64)ndx, NULL) < 0) {
            sdb_free(sdb);
            free(data);
            return NULL;
        }

        cursor += len;
    }

    free(data);
    return sdb;
}

Sdb* elf_process_version_definitions(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr) {
        return NULL;
    }

    // Allocate memory for version definitions
    Elf_(Addr)* verdefs = malloc(sz);
    if (!verdefs) {
        return NULL;
    }

    // Retrieve section names
    const char* secname = elf_section_name(bin, shdr->sh_name);
    if (!secname) {
        free(verdefs);
        return NULL;
    }

    Sdb* sdb = sdb_new0();
    if (!sdb) {
        free(verdefs);
        return NULL;
    }

    // Iterate through version definitions
    Elf_(Addr)* vd = verdefs;
    while ((size_t)(vd - verdefs) < sz) {
        uint16_t vdx = *(uint16_t*)vd;
        vd += 1;

        // Read attributes of the version definition
        char* name = (char*)vd;
        uint16_t ndx = *(uint16_t*)(vd + 1);
        uint16_t hash = *(uint16_t*)(vd + 2);

        // Store the version information in the Sdb
        char key[256];
        snprintf(key, sizeof(key), "%s.%s", secname, name);
        if (!sdb_num_set(sdb, key, ndx, 0)) {
            sdb_free(sdb);
            free(verdefs);
            return NULL;
        }

        if (!sdb_num_set(sdb, key, hash, 0)) {
            sdb_free(sdb);
            free(verdefs);
            return NULL;
        }

        // Process auxiliary entries if applicable
        while ((size_t)(vd - verdefs) < sz && *vd != 0) {
            // Skip auxiliary data
            vd += 1;
        }

        // Move to the next version definition
        vd += 1;
    }

    free(verdefs);
    return sdb;
}

#include <stdlib.h>
#include <string.h>

Sdb* elf_process_version_definitions(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Elf_(Word) link_ndx = shdr->sh_link;
    Elf_(Shdr)* link_shdr = NULL;

    if (link_ndx < bin->shnum && link_ndx < bin->shdr_count) {
        link_shdr = bin->shdr + link_ndx;
    } else {
        return NULL;
    }

    Elf_(Word)* data = NULL;
    if (shdr->sh_size > 0) {
        data = malloc(shdr->sh_size);
        if (!data) {
            return NULL;
        }
        memcpy(data, bin->data + shdr->sh_offset, shdr->sh_size);
    }

    Sdb* sdb = sdb_new0();
    if (!sdb) {
        free(data);
        return NULL;
    }

    Elf_(Word) offset = 0;
    while (offset < shdr->sh_size) {
        Elf_(Word) verdef = *(Elf_(Word)*)(data + offset);
        if (verdef == 0) {
            break;
        }

        Elf_(Word) name_offset = *(Elf_(Word)*)(data + offset + 4);
        Elf_(Word) hash = *(Elf_(Word)*)(data + offset + 8);
        Elf_(Word) flags = *(Elf_(Word)*)(data + offset + 12);
        Elf_(Word) next = *(Elf_(Word)*)(data + offset + 16);

        char* name = (char*)malloc(strlen(link_shdr->name) + name_offset + 1);
        if (!name) {
            sdb_free(sdb);
            free(data);
            return NULL;
        }

        snprintf(name, strlen(link_shdr->name) + name_offset + 1, "%s", link_shdr->name + name_offset);

        char key[256];
        snprintf(key, sizeof(key), "version.%s", name);
        if (sdb_num_put(sdb, key, hash, NULL) == NULL) {
            free(name);
            sdb_free(sdb);
            free(data);
            return NULL;
        }

        Elf_(Word) aux_offset = offset + 20;
        while (aux_offset < shdr->sh_size) {
            Elf_(Word) aux = *(Elf_(Word)*)(data + aux_offset);
            if (aux == 0) {
                break;
            }
            aux_offset += 8;
        }

        offset += next;
    }

    free(data);
    return sdb;
}

#include <stdlib.h>
#include <string.h>

Sdb* process_version_definitions(ELFOBJ* bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    size_t num_entries = sz / sizeof(Elf_Verdef);
    Elf_Verdef* verdefs = malloc(sz);
    if (!verdefs) {
        return NULL;
    }

    if (elf_get_section_names(bin, shdr) < 0) {
        free(verdefs);
        return NULL;
    }

    Sdb* sdb = sdb_new0();
    if (!sdb) {
        free(verdefs);
        return NULL;
    }

    Elf_Verdef* vdef;
    for (size_t i = 0; i < num_entries; i++) {
        vdef = &verdefs[i];

        char key[256];
        snprintf(key, sizeof(key), "version.%zd", i);
        if (sdb_set(sdb, key, vdef->vd_version, 0) < 0) {
            sdb_free(sdb);
            free(verdefs);
            return NULL;
        }

        Elf_Verdaux* aux = (Elf_Verdaux*)((uint8_t*)vdef + vdef->vd_aux);
        if (aux) {
            snprintf(key, sizeof(key), "aux.%zd", i);
            if (sdb_set(sdb, key, aux->vda_name, 0) < 0) {
                sdb_free(sdb);
                free(verdefs);
                return NULL;
            }
        }
    }

    free(verdefs);
    return sdb;
}
